54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Dedicated audit logger: on a successful create an audit line records the owner id,
64	     * customerCode and registrationDate. */
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
68	    private static final int CITY_CAPACITY = 50;
69	
70	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
71	     * create is rejected once this many owners already carry today's registration date. */
72	    private static final int DAILY_REGISTRATION_LIMIT = 100;
73	
74	    /** Once more than this many owners already carry a given day's registration date, a new owner
75	     * created for that day is flagged with {@code bulkSignupWarning} to signal a bulk-signup surge. */
76	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
77	
78	    /** HTTP header carrying the client-supplied idempotency key for a create. */
79	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    private final HttpServletRequest request;
90	
91	    private final IdempotencyStore idempotencyStore;
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper,
97	                                 HttpServletRequest request,
98	                                 IdempotencyStore idempotencyStore) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	        this.request = request;
104	        this.idempotencyStore = idempotencyStore;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        // Idempotent create: if this request carries an Idempotency-Key we have already created an
136	        // owner for, return that original owner with 200 OK instead of creating a duplicate.
137	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
138	        boolean hasIdempotencyKey = idempotencyKey != null && !idempotencyKey.isBlank();
139	        if (hasIdempotencyKey) {
140	            Optional<Owner> existing = this.idempotencyStore.find(idempotencyKey)
141	                .map(this.clinicService::findOwnerById);
142	            if (existing.isPresent()) {
143	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing.get()), HttpStatus.OK);
144	            }
145	        }
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        // The effective registration date (supplied, or the server date when omitted) must fall on
149	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
150	        // registration date — the stored value, the per-day limit below and the membership number —
151	        // uses this adjusted date.
152	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
153	        owner.setRegistrationDate(effectiveDate);
154	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
155	        // further creates for that day with 429 Too Many Requests.
156	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
157	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
158	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
159	        }
160	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
161	        // for its registration date, signalling a bulk-signup surge.
162	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
163	        // Per-city capacity: a city that already holds the maximum number of owners is full.
164	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
165	            return new ResponseEntity<>(HttpStatus.CONFLICT);
166	        }
167	        // The household id is derived deterministically on the owner itself (see
168	        // Owner.getHouseholdId()) from its normalized last name and postcode, so owners sharing a
169	        // last name and postcode share it automatically — no linking step and no ordering to manage.
170	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
171	        // Exact-identity hard duplicate: reject with 409 when the new owner's WHOLE identityKey
172	        // (normalized telephone | email-or-empty | householdId) equals an existing owner's. A
173	        // truly identical record is always rejected, independent of sharesHousehold.
174	        if (this.clinicService.isIdentityKeyInUse(owner)) {
175	            return new ResponseEntity<>(HttpStatus.CONFLICT);
176	        }
177	        // Household duplicate: another owner already belongs to this (last name, postcode)
178	        // household. Reject with 409 unless the caller declares the shared household via
179	        // sharesHousehold, which bypasses the block and creates this owner as a declared member.
180	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner);
181	        if (householdInUse && !sharesHousehold) {
182	            return new ResponseEntity<>(HttpStatus.CONFLICT);
183	        }
184	        // Soft "possible duplicate" detection: an existing owner shares this owner's last name and
185	        // postcode with a different telephone. A declared household member (sharesHousehold on an
186	        // in-use household) is an intentional share, not a suspected duplicate, so it is not
187	        // flagged; otherwise the create still proceeds, flagged with possibleDuplicate=true and
188	        // possibleDuplicateOf set to the matching owner id.
189	        Integer possibleDuplicateOf = (householdInUse && sharesHousehold)
190	            ? null
191	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
192	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
193	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
194	        owner.setNamesakeCount(
195	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
196	        this.clinicService.saveOwner(owner);
197	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
198	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
199	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
200	        if (hasIdempotencyKey) {
201	            this.idempotencyStore.record(idempotencyKey, owner.getId());
202	        }
203	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
204	        headers.setLocation(UriComponentsBuilder.newInstance()
205	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
206	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
212	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
213	        if (currentOwner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
217	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
218	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
219	        currentOwner.setCity(ownerFieldsDto.getCity());
220	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
221	        currentOwner.setLastName(ownerFieldsDto.getLastName());
222	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
223	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
224	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
225	        this.clinicService.saveOwner(currentOwner);
226	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Transactional
231	    @Override
232	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
233	        Owner owner = this.clinicService.findOwnerById(ownerId);
234	        if (owner == null) {
235	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	        }
237	        this.clinicService.deleteOwner(owner);
238	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
244	        Owner owner = this.clinicService.findOwnerById(ownerId);
245	        if (owner == null) {
246	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	        }
248	        HttpHeaders headers = new HttpHeaders();
249	        Pet pet = petMapper.toPet(petFieldsDto);
250	        owner.setId(ownerId);
251	        pet.setOwner(owner);
252	        pet.getType().setName(null);
253	        this.clinicService.savePet(pet);
254	        PetDto petDto = petMapper.toPetDto(pet);
255	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
256	            .buildAndExpand(pet.getId()).toUri());
257	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
258	    }
259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
263	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
264	        if (currentOwner != null) {
265	            Pet currentPet = this.clinicService.findPetById(petId);
266	            if (currentPet != null) {
267	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
268	                currentPet.setName(petFieldsDto.getName());
269	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
270	                this.clinicService.savePet(currentPet);
271	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
272	            }
273	        }
274	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	    }
276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Override
279	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
280	        HttpHeaders headers = new HttpHeaders();
281	        Visit visit = visitMapper.toVisit(visitFieldsDto);
282	        Pet pet = new Pet();
283	        pet.setId(petId);
284	        visit.setPet(pet);
285	        this.clinicService.saveVisit(visit);
286	        VisitDto visitDto = visitMapper.toVisitDto(visit);
287	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
288	            .buildAndExpand(visit.getId()).toUri());
289	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
290	    }
291	
292	
293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Override
295	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
296	        Owner owner = this.clinicService.findOwnerById(ownerId);
297	        if (owner != null) {
298	            Pet pet = owner.getPet(petId);
299	            if (pet != null) {
300	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
301	            }
302	        }
303	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
304	    }
305	}
