252	    /**
253	     * Build a {@code customerCode} of the form {@code <REGION>-<HASH8>}: the region code derived
254	     * from the owner's postcode (see {@link Regions#forPostcode}), a hyphen, and {@code HASH8} —
255	     * the first eight upper-case hex characters of the SHA-256 of the owner's normalized telephone
256	     * concatenated with its last name (e.g. {@code NSW-3F5A9C2E}). The identity carries no sequence
257	     * number, so it depends only on the owner's own postcode, telephone and last name.
258	     *
259	     * <p>If the computed code collides with an existing owner's {@code customerCode}, {@code -<n>}
260	     * is appended with the smallest {@code n} of 2 or more that makes it unique, and the
261	     * de-duplicated code is returned.
262	     */
263	    private String generateCustomerCode(Owner owner) {
264	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
265	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
266	        String base = Regions.forPostcode(owner.getPostcode()) + "-" + hash8(telephone + lastName);
267	        return deduplicateCustomerCode(base, owner);
268	    }
269	
270	    /**
271	     * Return {@code base} if no other owner already uses it as a {@code customerCode}; otherwise
272	     * append {@code -<n>} with the smallest {@code n >= 2} that is not already taken, so distinct
273	     * owners always receive distinct customer codes.
274	     */
275	    private String deduplicateCustomerCode(String base, Owner owner) {
276	        Set<String> existing = ownerRepository.findAll().stream()
277	            .filter(other -> other != owner)
278	            .map(Owner::getCustomerCode)
279	            .filter(Objects::nonNull)
280	            .collect(Collectors.toSet());
281	        if (!existing.contains(base)) {
282	            return base;
283	        }
284	        int n = 2;
285	        while (existing.contains(base + "-" + n)) {
286	            n++;
287	        }
288	        return base + "-" + n;
289	    }
