362	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName())))
363	            .filter(existing -> postcode.equals(existing.getPostcode()))
364	            .filter(existing -> telephone == null
365	                ? existing.getTelephone() != null
366	                : !telephone.equals(existing.getTelephone()))
367	            .map(Owner::getId)
368	            .min(Integer::compareTo)
369	            .orElse(null);
370	    }
371	
372	    @Override
373	    @Transactional(readOnly = true)
374	    public int countNamesakes(String firstName, String lastName) throws DataAccessException {
375	        if (firstName == null || lastName == null) {
376	            return 0;
377	        }
378	        return (int) ownerRepository.findAll().stream()
379	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
380	                && lastName.equalsIgnoreCase(existing.getLastName()))
381	            .count();
382	    }
383	
384	    @Override
385	    @Transactional(readOnly = true)
386	    public int countOwnersInCity(String city) throws DataAccessException {
387	        String normalized = normalizeForComparison(city);
388	        if (normalized == null) {
389	            return 0;
390	        }
391	        return (int) ownerRepository.findAll().stream()
392	            .filter(existing -> normalized.equals(normalizeForComparison(existing.getCity())))
393	            .count();
394	    }
395	
396	    @Override
397	    @Transactional(readOnly = true)
398	    public int countOwnersRegisteredOn(LocalDate date) throws DataAccessException {
399	        if (date == null) {
400	            return 0;
401	        }
402	        return (int) ownerRepository.findAll().stream()
403	            .filter(existing -> date.equals(existing.getRegistrationDate()))
404	            .count();
405	    }
406	
407	    @Override
408	    @Transactional(readOnly = true)
409	    public Collection<Visit> findVisitsByPetId(int petId) {
410	        return visitRepository.findByPetId(petId);
411	    }
412	
413	    @Override
414	    @Transactional(readOnly = true)
415	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
416	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
417	    }
418	
419	    private <T> T findEntityById(Supplier<T> supplier) {
420	        try {
421	            return supplier.get();
422	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
423	            // Just ignore not found exceptions for Jdbc/Jpa realization
424	            return null;
425	        }
426	    }
