2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Rolls a calendar date forward onto a business day.
9	 *
10	 * <p>A business day is any day that is not a Saturday, Sunday or listed public holiday. When the
11	 * supplied date already falls on a business day it is returned unchanged; otherwise it is rolled
12	 * forward one day at a time until it lands on a business day. The operation is idempotent: feeding
13	 * it an already-adjusted value returns that same value.
14	 */
15	public final class BusinessDays {
16	
17	    /** Fixed public holidays that are skipped by the business-day roll. */
18	    private static final Set<LocalDate> HOLIDAYS = Set.of(
19	        LocalDate.parse("2026-01-01"),
20	        LocalDate.parse("2026-01-26"),
21	        LocalDate.parse("2026-04-25"),
22	        LocalDate.parse("2026-12-25"),
23	        LocalDate.parse("2026-12-28"));
24	
25	    private BusinessDays() {
26	    }
27	
28	    /**
29	     * Return {@code date} when it falls on a business day, otherwise roll it forward to the next
30	     * day that is neither a weekend nor a listed public holiday. Returns {@code null} when the
31	     * input is {@code null}.
32	     */
33	    public static LocalDate rollToBusinessDay(LocalDate date) {
34	        if (date == null) {
35	            return null;
36	        }
37	        while (!isBusinessDay(date)) {
38	            date = date.plusDays(1);
39	        }
40	        return date;
41	    }
42	
43	    private static boolean isBusinessDay(LocalDate date) {
44	        DayOfWeek day = date.getDayOfWeek();
45	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
46	    }
47	
48	    /**
49	     * Resolve the effective registration date: the supplied date, or the server's current date
50	     * when {@code null}, rolled forward onto a business day. This is the single definition of the
51	     * "default-to-now, then roll" policy shared by the create controller (which needs the value
52	     * eagerly) and the {@code @PrePersist} backstop. Idempotent for an already-adjusted value.
53	     */
54	    public static LocalDate effectiveRegistrationDate(LocalDate supplied) {
55	        return rollToBusinessDay(supplied != null ? supplied : LocalDate.now());
56	    }
57	}
