3	import jakarta.validation.ConstraintValidator;
4	import jakarta.validation.ConstraintValidatorContext;
5	
6	import java.util.Set;
7	
8	/**
9	 * Rejects an owner's email address when its domain is on the disposable-domain blocklist.
10	 * Syntactic validity is enforced separately by the field's {@code @Email} constraint, so a
11	 * {@code null} value is accepted here (an optional email) and any value without a domain part
12	 * is left for that constraint. The domain is compared case-insensitively.
13	 */
14	public class EmailDomainValidator implements ConstraintValidator<EmailDomainValidation, String> {
15	
16	    private static final Set<String> DISPOSABLE_DOMAINS =
17	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
18	
19	    @Override
20	    public boolean isValid(String email, ConstraintValidatorContext context) {
21	        if (email == null) {
22	            return true; // optional; presence/syntax handled by other constraints
23	        }
24	        int at = email.lastIndexOf('@');
25	        if (at < 0 || at == email.length() - 1) {
26	            return true; // no domain part; leave to the @Email constraint
27	        }
28	        String domain = email.substring(at + 1).toLowerCase();
29	        return !DISPOSABLE_DOMAINS.contains(domain);
30	    }
31	}
