1	package org.springframework.samples.petclinic.service;
2	
3	import java.util.Map;
4	import java.util.Optional;
5	import java.util.concurrent.ConcurrentHashMap;
6	
7	import org.springframework.stereotype.Component;
8	
9	/**
10	 * Remembers which entity a given client-supplied {@code Idempotency-Key} has already created, so a
11	 * repeated create carrying the same key can return the originally created entity instead of
12	 * creating a duplicate.
13	 *
14	 * <p>The store owns the keying and concurrency concerns on behalf of its callers; it is the single
15	 * place to evolve this behaviour later (e.g. TTL/eviction or cross-restart persistence) without
16	 * touching the request handlers that use it. The current implementation keeps the mapping in memory.
17	 */
18	@Component
19	public class IdempotencyStore {
20	
21	    private final Map<String, Integer> keyToId = new ConcurrentHashMap<>();
22	
23	    /** The id previously recorded for {@code key}, or empty if the key has not been seen. */
24	    public Optional<Integer> find(String key) {
25	        return Optional.ofNullable(keyToId.get(key));
26	    }
27	
28	    /** Remember that {@code key} created the entity with the given {@code id}. */
29	    public void record(String key, Integer id) {
30	        keyToId.put(key, id);
31	    }
32	}
