1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Validates an owner's postcode against the region derived from its city.
7	 *
8	 * <p>A postcode is a 4-digit string. When present it must fall within the inclusive
9	 * range fixed for the region of the owner's city, keyed via a fixed city-to-region
10	 * table:
11	 * <ul>
12	 *     <li>Sydney -&gt; NSW, postcodes 2000-2099;</li>
13	 *     <li>Melbourne -&gt; VIC, postcodes 3000-3099;</li>
14	 *     <li>Brisbane -&gt; QLD, postcodes 4000-4099.</li>
15	 * </ul>
16	 *
17	 * <p>A city with no known region accepts any 4-digit postcode. The postcode is
18	 * optional, so a {@code null} postcode is always accepted; the 4-digit format is
19	 * enforced separately by the field's pattern constraint, so a value that is not a
20	 * 4-digit number is left for that constraint to reject.
21	 */
22	public final class Postcodes {
23	
24	    /**
25	     * Known city-to-region mappings, keyed by the exact city name.
26	     */
27	    private static final Map<String, String> CITY_REGIONS = Map.of(
28	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
29	
30	    /**
31	     * Region to its inclusive 4-digit postcode range {@code {low, high}}.
32	     */
33	    private static final Map<String, int[]> REGION_RANGES = Map.of(
34	        "NSW", new int[] {2000, 2099},
35	        "VIC", new int[] {3000, 3099},
36	        "QLD", new int[] {4000, 4099});
37	
38	    private Postcodes() {
39	    }
40	
41	    /**
42	     * Whether the given postcode is acceptable for the given city. Returns {@code true} when the
43	     * postcode is {@code null} (optional), when it is not a 4-digit value (deferred to the format
44	     * constraint), or when the city has no known region. Otherwise the 4-digit value must lie within
45	     * the inclusive range for the city's region.
46	     */
47	    public static boolean isValidForCity(String postcode, String city) {
48	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
49	            return true;
50	        }
51	        String region = CITY_REGIONS.get(city);
52	        int[] range = region == null ? null : REGION_RANGES.get(region);
53	        if (range == null) {
54	            return true;
55	        }
56	        int value = Integer.parseInt(postcode);
57	        return value >= range[0] && value <= range[1];
58	    }
59	}
