1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives the canonical region code from an owner's postcode.
7	 *
8	 * <p>A region is identified solely by the 4-digit postcode, keyed via a fixed
9	 * region-to-range table:
10	 * <ul>
11	 *     <li>NSW, postcodes 2000-2099;</li>
12	 *     <li>VIC, postcodes 3000-3099;</li>
13	 *     <li>QLD, postcodes 4000-4099.</li>
14	 * </ul>
15	 *
16	 * <p>This is the single rule behind the {@code <REGION>} segment of an owner's
17	 * {@code customerCode} and the owner's derived locality. A {@code null} postcode,
18	 * a value that is not a 4-digit number, or a 4-digit value outside every known
19	 * range all derive the region {@code "UNKNOWN"}.
20	 */
21	public final class Regions {
22	
23	    /**
24	     * Region to its inclusive 4-digit postcode range {@code {low, high}}.
25	     */
26	    private static final Map<String, int[]> REGION_RANGES = Map.of(
27	        "NSW", new int[] {2000, 2099},
28	        "VIC", new int[] {3000, 3099},
29	        "QLD", new int[] {4000, 4099});
30	
31	    /**
32	     * Region to its IANA timezone name, via a fixed region-to-timezone table.
33	     */
34	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
35	        "NSW", "Australia/Sydney",
36	        "VIC", "Australia/Melbourne",
37	        "QLD", "Australia/Brisbane");
38	
39	    /**
40	     * The region code a {@code "UNKNOWN"} postcode (absent, non-4-digit, or in no known range)
41	     * derives to.
42	     */
43	    public static final String UNKNOWN = "UNKNOWN";
44	
45	    private Regions() {
46	    }
47	
48	    /**
49	     * The canonical region code for the given postcode: the region whose inclusive 4-digit range
50	     * contains the postcode, or {@link #UNKNOWN} when the postcode is {@code null}, not a 4-digit
51	     * value, or outside every known range.
52	     */
53	    public static String forPostcode(String postcode) {
54	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
55	            return UNKNOWN;
56	        }
57	        int value = Integer.parseInt(postcode);
58	        for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
59	            int[] range = entry.getValue();
60	            if (value >= range[0] && value <= range[1]) {
61	                return entry.getKey();
62	            }
63	        }
64	        return UNKNOWN;
65	    }
66	
67	    /**
68	     * The IANA timezone name for the given region code, via a fixed region-to-timezone table
69	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane), or
70	     * {@code null} when the region is {@code null} or not in the table (e.g. {@link #UNKNOWN}).
71	     */
72	    public static String timezoneForRegion(String region) {
73	        return region == null ? null : REGION_TIMEZONES.get(region);
74	    }
75	}
